"""Authored communicative syllabus used by the existing practice modules.

Each level has its own twenty units, vocabulary and three transfer cases.
Grammar keys refer to the existing theory catalogue; this is content, not
another exercise engine. Later cycles revisit skills in new situations.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Unit:
    key: str
    title: str
    grammar: str
    objective: str
    task: str
    words: tuple[tuple[str, str], ...]
    prompts: tuple[str, ...]
    cases: tuple[str, ...]
    goals: tuple[str, ...] = ('daily',)


